"""Offline, self-contained research report. Embedded data is script-safe."""
import json
import os
from pathlib import Path
import tempfile


def save_html(path, html):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=path.parent, delete=False) as handle:
            temporary = Path(handle.name)
            handle.write(html)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        if temporary is not None and temporary.exists():
            temporary.unlink()
    return path


def write_dashboard(path, report, replay_result=None):
    data = json.dumps({"report": report, "replay": replay_result}, ensure_ascii=False, allow_nan=False)
    data = data.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    html = TEMPLATE.replace("__PAYLOAD__", data)
    return save_html(path, html)


